import{_ as i,I as r,c as s,o as t,a3 as n,b as l,w as a,a as g,J as c,a4 as d}from"./chunks/framework.Cc9k46oU.js";const w=JSON.parse('{"title":"XP, Scrum, and Kanban: Comparison and Practical Adoption Strategy","description":"A comprehensive guide to understanding the differences and relationships among XP, Scrum, and Kanban at a glance, and integrating all three agile methodologies in practice. Includes step-by-step checklists and diagrams to help you improve project management and software quality.","frontmatter":{"title":"XP, Scrum, and Kanban: Comparison and Practical Adoption Strategy","description":"A comprehensive guide to understanding the differences and relationships among XP, Scrum, and Kanban at a glance, and integrating all three agile methodologies in practice. Includes step-by-step checklists and diagrams to help you improve project management and software quality.","head":[["meta",{"name":"keywords","content":"Agile Methodology,XP (eXtreme Programming),Scrum,Kanban,Scrumban,Software Development Process,Agile Integration Guide,Agile Practices,Software Quality Improvement,Project Management"}],["meta",{"property":"og:title","content":"Developer Roles in the AI Era: XP, Scrum, and Kanban Integration Guide | Agile Methodology Comparison"}],["meta",{"property":"og:description","content":"A comprehensive guide to understanding the differences and relationships among XP, Scrum, and Kanban at a glance, and integrating all three agile methodologies in practice. Includes step-by-step checklists and diagrams to help you improve project management and software quality."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/agile/xp_scrum_kanban"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/agile/xp_scrum_kanban"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/xp_scrum_kanban"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/xp_scrum_kanban"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/xp_scrum_kanban"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/xp_scrum_kanban"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"XP, Scrum, and Kanban: Comparison and Practical Adoption Strategy | Empasy Docs"}],["meta",{"property":"og:description","content":"A comprehensive guide to understanding the differences and relationships among XP, Scrum, and Kanban at a glance, and integrating all three agile methodologies in practice. Includes step-by-step checklists and diagrams to help you improve project management and software quality."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/agile/xp_scrum_kanban"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"XP, Scrum, and Kanban: Comparison and Practical Adoption Strategy | Empasy Docs"}],["meta",{"name":"twitter:description","content":"A comprehensive guide to understanding the differences and relationships among XP, Scrum, and Kanban at a glance, and integrating all three agile methodologies in practice. Includes step-by-step checklists and diagrams to help you improve project management and software quality."}]],"sort":8000},"headers":[],"relativePath":"en/agile/xp_scrum_kanban.md","filePath":"en/agile/xp_scrum_kanban.md","lastUpdated":1795293539000}'),m={name:"en/agile/xp_scrum_kanban.md"};function p(h,e,u,f,b,y){const o=r("Mermaid");return t(),s("div",null,[e[1]||(e[1]=n('<h2 id="xp-scrum-and-kanban-integration-guide-comparing-agile-development-methodologies-and-practical-adoption-strategies" tabindex="-1">XP, Scrum, and Kanban Integration Guide: Comparing Agile Development Methodologies and Practical Adoption Strategies <a class="header-anchor" href="#xp-scrum-and-kanban-integration-guide-comparing-agile-development-methodologies-and-practical-adoption-strategies" aria-label="Permalink to “XP, Scrum, and Kanban Integration Guide: Comparing Agile Development Methodologies and Practical Adoption Strategies”">​</a></h2><h3 id="introduction-the-essence-and-evolution-of-agile" tabindex="-1">Introduction: The Essence and Evolution of Agile <a class="header-anchor" href="#introduction-the-essence-and-evolution-of-agile" aria-label="Permalink to “Introduction: The Essence and Evolution of Agile”">​</a></h3><p>True to the meaning of &quot;agile,&quot; Agile is a collection of software development philosophies and frameworks designed to respond rapidly to changing requirements and continuously deliver value. Published in 2001, the Manifesto for Agile Software Development values <strong>individuals and interactions</strong> over processes and tools, <strong>working software</strong> over comprehensive documentation, <strong>customer collaboration</strong> over contract negotiation, and <strong>responding to change</strong> over following a plan.</p><p>This guide compares and analyzes three representative methodologies that put Agile into practice—eXtreme Programming (XP), Scrum, and Kanban—explains how they relate to one another, and presents a practical approach to combining them into an integrated workflow.</p><hr><h3 id="_1-comparing-xp-scrum-and-kanban" tabindex="-1">1. Comparing XP, Scrum, and Kanban <a class="header-anchor" href="#_1-comparing-xp-scrum-and-kanban" aria-label="Permalink to “1. Comparing XP, Scrum, and Kanban”">​</a></h3><h4 id="_1-1-extreme-programming-xp-—-engineering-practices" tabindex="-1"><strong>1.1 eXtreme Programming (XP) — Engineering Practices</strong> <a class="header-anchor" href="#_1-1-extreme-programming-xp-—-engineering-practices" aria-label="Permalink to “1.1 eXtreme Programming (XP) — Engineering Practices”">​</a></h4><p>XP is a <strong>development framework</strong> focused on improving software quality and maximizing a development team&#39;s productivity and responsiveness. Its core objective is to respond effectively to rapidly changing customer requirements.</p><ul><li><p><strong>Philosophy:</strong> &quot;If something is good, doing it to the extreme is even better.&quot;</p></li><li><p><strong>Scope:</strong> Primarily deeply involved in the software <strong>code development phase</strong>.</p></li><li><p><strong>Cadence:</strong> Development proceeds in short cycles called <strong>Iterations</strong> (typically 1–2 weeks).</p></li><li><p><strong>Core Practices:</strong></p></li><li><p><strong>Pair Programming:</strong> Two developers work together at a single workstation, reviewing code in real time and sharing knowledge.</p></li><li><p><strong>Test-Driven Development (TDD):</strong> Write a <strong>failing test first</strong> for the code to be implemented, then write the minimum amount of code required to pass that test. Repeating this cycle increases code reliability.</p></li><li><p><strong>Continuous Integration (CI):</strong> Integrate code into the main repository multiple times a day and run automated tests to catch issues early.</p></li><li><p><strong>Refactoring:</strong> Improve the internal structure of code without altering its external behavior, increasing readability and maintainability.</p></li><li><p><strong>Simple Design:</strong> Design the simplest system that satisfies the current requirements.</p></li><li><p><strong>Collective Code Ownership:</strong> Any team member can modify any part of the system.</p></li><li><p><strong>On-Site Customer:</strong> A customer representative is co-located with the development team or readily accessible at all times.</p></li><li><p><strong>Pros:</strong> High code quality, fewer defects, minimized technical debt, reduced fear of change.</p></li><li><p><strong>Cons:</strong> Steep learning curve and high focus required to adopt practices, potential resistance to pair programming, difficulty securing an on-site customer.</p></li></ul><h4 id="_1-2-scrum-—-project-management-framework" tabindex="-1"><strong>1.2 Scrum — Project Management Framework</strong> <a class="header-anchor" href="#_1-2-scrum-—-project-management-framework" aria-label="Permalink to “1.2 Scrum — Project Management Framework”">​</a></h4><p>Scrum is a <strong>project management framework</strong> for developing and managing complex products. It clearly defines roles, decision-making structures, and events—establishing who does what and when.</p><ul><li><p><strong>Philosophy:</strong> Grounded in empiricism, solving complex problems through a cycle of <strong>transparency, inspection, and adaptation</strong>.</p></li><li><p><strong>Scope:</strong> Applied across the overall project <strong>management and collaboration process</strong>.</p></li><li><p><strong>Cadence:</strong> Work proceeds in fixed-length time-boxes called <strong>Sprints</strong> (typically 2–4 weeks).</p></li><li><p><strong>Core Roles:</strong></p><ul><li><strong>Product Owner (PO):</strong> Accountable for maximizing product value; manages and prioritizes requirements in the <strong>Product Backlog</strong>.</li><li><strong>Scrum Master (SM):</strong> Coaches the team to follow Scrum effectively and removes impediments. Acts as a <strong>servant leader</strong> rather than a traditional manager.</li><li><strong>Development Team:</strong> A cross-functional, self-organizing team that actually builds the product.</li></ul></li><li><p><strong>Core Artifacts:</strong></p><ul><li><strong>Product Backlog:</strong> A prioritized list of all features, enhancements, and fixes needed for the product.</li><li><strong>Sprint Backlog:</strong> The Product Backlog items selected for the current sprint along with a plan for delivering them.</li><li><strong>Increment:</strong> The &quot;working product&quot; outcome produced at the end of a sprint.</li></ul></li><li><p><strong>Core Events:</strong> (All Time-boxed)</p><ul><li><strong>Sprint Planning:</strong> Plan what will be delivered and how the work will be accomplished.</li><li><strong>Daily Scrum:</strong> A 15-minute sync to share progress and surface blockers.</li><li><strong>Sprint Review:</strong> Demonstrate the Increment to customers/stakeholders and gather feedback.</li><li><strong>Sprint Retrospective:</strong> Inspect the team&#39;s process and identify actionable improvements.</li></ul></li><li><p><strong>Pros:</strong> Clear roles and responsibilities, regular feedback and adaptation, transparent progress, encourages team self-organization.</p></li><li><p><strong>Cons:</strong> Provides no direct guidance on engineering practices (quality depends on the team); rigidity from prohibiting mid-sprint scope changes (changes must wait until the next sprint).</p></li></ul><h4 id="_1-3-kanban-—-continuous-flow-improvement-system" tabindex="-1"><strong>1.3 Kanban — Continuous Flow Improvement System</strong> <a class="header-anchor" href="#_1-3-kanban-—-continuous-flow-improvement-system" aria-label="Permalink to “1.3 Kanban — Continuous Flow Improvement System”">​</a></h4><p>Kanban is a <strong>continuous flow system</strong> that visualizes <strong>workflow</strong> and limits Work In Progress (WIP) to maximize efficiency. It focuses on evolutionary, incremental process improvement.</p><ul><li><p><strong>Philosophy:</strong> &quot;Start with what you do now, and pursue continuous improvement through incremental, evolutionary change.&quot;</p></li><li><p><strong>Scope:</strong> <strong>Applicable to any process</strong> (development, maintenance, marketing, HR, etc.).</p></li><li><p><strong>Cadence:</strong> <strong>Continuous.</strong> There is no time-box; as soon as one work item is completed, the next item is pulled in.</p></li><li><p><strong>Core Practices:</strong></p><ul><li><strong>Visualize:</strong> Use a <strong>Kanban Board</strong> to make workflow stages and item states (e.g., To Do, In Progress, Done) visible at a glance.</li><li><strong>Limit Work In Progress (WIP Limit):</strong> Cap the maximum number of items allowed in each stage (especially &quot;In Progress&quot;) simultaneously. This exposes bottlenecks and improves team focus.</li><li><strong>Manage Flow:</strong> Observe how items move across the board, measure queues, delays, and bottlenecks, and continuously smooth the flow.</li><li><strong>Make Policies Explicit:</strong> Clearly define each workflow stage and the Definition of Done (DoD).</li><li><strong>Feedback Loops:</strong> Hold regular operations and delivery review meetings to inspect flow and quality.</li></ul></li><li><p><strong>Pros:</strong> Highly flexible with immediate responsiveness to change, low barrier to adoption, excels at identifying bottlenecks and shortening Cycle Time.</p></li><li><p><strong>Cons:</strong> Without clear roles and deadlines, teams lacking discipline may struggle; harder to establish long-term plans; pace of change can be gradual.</p></li></ul><h4 id="_1-4-comparison-summary-table" tabindex="-1"><strong>1.4 Comparison Summary Table</strong> <a class="header-anchor" href="#_1-4-comparison-summary-table" aria-label="Permalink to “1.4 Comparison Summary Table”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Attribute</th><th style="text-align:left;"><strong>eXtreme Programming (XP)</strong></th><th style="text-align:left;"><strong>Scrum</strong></th><th style="text-align:left;"><strong>Kanban</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Essence</strong></td><td style="text-align:left;"><strong>Set of engineering practices</strong></td><td style="text-align:left;"><strong>Project management framework</strong></td><td style="text-align:left;"><strong>Continuous flow improvement system</strong></td></tr><tr><td style="text-align:left;"><strong>Focus</strong></td><td style="text-align:left;">Code quality, technical excellence</td><td style="text-align:left;">Team collaboration, value delivery, adaptation</td><td style="text-align:left;">Workflow efficiency, reducing wait time</td></tr><tr><td style="text-align:left;"><strong>Cadence</strong></td><td style="text-align:left;">Iteration (1–2 weeks)</td><td style="text-align:left;">Sprint (2–4 weeks, fixed)</td><td style="text-align:left;">Continuous (no time-box)</td></tr><tr><td style="text-align:left;"><strong>Change Handling</strong></td><td style="text-align:left;">Permitted even within an Iteration</td><td style="text-align:left;">No changes during a Sprint</td><td style="text-align:left;">Anytime (highly flexible)</td></tr><tr><td style="text-align:left;"><strong>Roles</strong></td><td style="text-align:left;">Coach, Customer, Developers</td><td style="text-align:left;">PO, SM, Development Team</td><td style="text-align:left;">No specific roles prescribed</td></tr><tr><td style="text-align:left;"><strong>Core Tools</strong></td><td style="text-align:left;">TDD, Pair Programming, CI</td><td style="text-align:left;">Sprint Backlog, Burndown Chart</td><td style="text-align:left;"><strong>Kanban Board, WIP Limit</strong></td></tr><tr><td style="text-align:left;"><strong>Key Metrics</strong></td><td style="text-align:left;">Unit test coverage, etc.</td><td style="text-align:left;">Sprint Velocity</td><td style="text-align:left;"><strong>Cycle Time, Throughput</strong></td></tr><tr><td style="text-align:left;"><strong>Best Fit</strong></td><td style="text-align:left;">Rapidly changing requirements, high quality demands</td><td style="text-align:left;">Clear goals and rapid value delivery needed</td><td style="text-align:left;">Maintenance, irregular workloads, incremental improvement</td></tr></tbody></table><hr><h3 id="_2-relationships-among-the-three-methodologies-complementary-and-evolutionary" tabindex="-1">2. Relationships Among the Three Methodologies: Complementary and Evolutionary <a class="header-anchor" href="#_2-relationships-among-the-three-methodologies-complementary-and-evolutionary" aria-label="Permalink to “2. Relationships Among the Three Methodologies: Complementary and Evolutionary”">​</a></h3><p>XP, Scrum, and Kanban are not competing methodologies. They solve different problems and stand in a <strong>complementary</strong> and <strong>evolutionary</strong> relationship.</p><ol><li><strong>Scrum + XP: The Most Common and Powerful Combination</strong></li></ol><ul><li>Scrum provides the management framework for <strong>&quot;What&quot;</strong> to build and <strong>&quot;When&quot;</strong> to deliver it.</li><li>XP provides the engineering practices for <strong>&quot;How&quot;</strong> to build it well.</li><li>Adopting XP practices (TDD, CI, Refactoring) so that a Scrum team can produce the Increment committed in each sprint with <strong>high quality</strong> and at a <strong>sustainable</strong> pace is completely natural. Think of Scrum as the skeleton and XP as the muscle.</li></ul><ol start="2"><li><strong>Kanban -&gt; Scrum: A Gradual Path to Agile Adoption</strong></li></ol><ul><li>Kanban improves processes incrementally without disrupting existing workflows, starting with visualization and WIP limits.</li><li>Organizations adopting Agile/Scrum for the first time can take an <strong>evolutionary approach</strong>: start with Kanban to visualize their current state and smooth flow, then gradually introduce Scrum&#39;s Roles, Events, and Artifacts.</li></ul><ol start="3"><li><strong>Scrum -&gt; Kanban: Extending Scrum&#39;s Flexibility (Scrumban)</strong></li></ol><ul><li>When a Scrum team needs a more flexible workflow without rigid sprint boundaries (for example, a maintenance team), it can blend in Kanban&#39;s flow-centric approach.</li><li>Known as <strong>Scrumban</strong>, this hybrid retains Scrum disciplines such as Sprint Planning, Reviews, and Retrospectives while managing daily stand-ups and task execution as a continuous flow using a Kanban board and WIP limits.</li></ul><hr><h3 id="_3-integrating-scrum-xp-and-kanban-in-practice" tabindex="-1">3. Integrating Scrum, XP, and Kanban in Practice <a class="header-anchor" href="#_3-integrating-scrum-xp-and-kanban-in-practice" aria-label="Permalink to “3. Integrating Scrum, XP, and Kanban in Practice”">​</a></h3><p>An ideal team blends the strengths of all three methodologies in harmony. Below is a systematic way to put this into practice.</p><h4 id="_3-1-integration-principles" tabindex="-1"><strong>3.1 Integration Principles</strong> <a class="header-anchor" href="#_3-1-integration-principles" aria-label="Permalink to “3.1 Integration Principles”">​</a></h4><ol><li><strong>Use Scrum as the Backbone:</strong> Follow Scrum&#39;s roles, events, and artifacts as the structural foundation for project management and collaboration.</li><li><strong>Guarantee Quality with XP Practices:</strong> Actively adopt XP practices during development to maintain high code quality and a sustainable pace.</li><li><strong>Improve Execution with Kanban Flow:</strong> Leverage a Kanban board and WIP limits to manage work flow inside each sprint and surface bottlenecks.</li></ol><h4 id="_3-2-step-by-step-checklist-integrated-adoption-roadmap" tabindex="-1"><strong>3.2 Step-by-Step Checklist (Integrated Adoption Roadmap)</strong> <a class="header-anchor" href="#_3-2-step-by-step-checklist-integrated-adoption-roadmap" aria-label="Permalink to “3.2 Step-by-Step Checklist (Integrated Adoption Roadmap)”">​</a></h4><p><strong>Phase 1: Preparation and Initial Setup (Months 1–2)</strong></p><ul><li>[ ] <strong>Stakeholder Training:</strong> Ensure all members (developers, managers, and customers) understand the core concepts of Scrum, XP, and Kanban and the goal of integrating them.</li><li>[ ] <strong>Establish the Scrum Structure:</strong></li><li>[ ] Designate a <strong>Product Owner</strong> and create the initial <strong>Product Backlog</strong>.</li><li>[ ] Designate a <strong>Scrum Master</strong>.</li><li>[ ] Form the <strong>Development Team</strong> (cross-functional whenever possible).</li><li>[ ] Decide on the <strong>Sprint cadence</strong> (e.g., 2 weeks).</li><li>[ ] <strong>Tooling Setup:</strong> Configure a collaboration tool with <strong>Kanban Board</strong> capabilities such as Jira, Trello, or Azure Boards (a physical board also works).</li></ul><p><strong>Phase 2: First Sprint Execution and XP Practice Adoption (Months 3–6)</strong></p><ul><li>[ ] <strong>Run Scrum Events:</strong></li><li>[ ] <strong>Sprint Planning:</strong> Build the Sprint Backlog together with the PO.</li><li>[ ] <strong>Daily Scrum:</strong> Review progress while looking at the Kanban Board (&quot;Talk to the board&quot;).</li><li>[ ] <strong>Sprint Review &amp; Retrospective:</strong> Review the first sprint outcome and discuss areas for improvement.</li><li>[ ] <strong>Leverage the Kanban Board:</strong></li><li>[ ] Place Sprint Backlog items in the &quot;To Do&quot; column of the Kanban Board.</li><li>[ ] Configure board columns to fit the team&#39;s workflow (e.g., <code>To Do</code> -&gt; <code>Development</code> -&gt; <code>Code Review</code> -&gt; <code>Testing</code> -&gt; <code>Done</code>).</li><li>[ ] <strong>Start applying a WIP Limit from the &quot;Development&quot; stage</strong> (e.g., number of developers * 1.5).</li><li>[ ] <strong>Adopt XP Practices (incrementally, one at a time):</strong></li><li>[ ] <strong>Adopt CI (Continuous Integration):</strong> Set up an automated build/test pipeline (<strong>highest priority</strong>).</li><li>[ ] <strong>Adopt TDD:</strong> Train the habit of writing test cases first, starting with core modules.</li><li>[ ] <strong>Allocate refactoring time:</strong> Explicitly include refactoring work as tasks during sprint planning.</li></ul><p><strong>Phase 3: Maturation and Optimization (6+ Months)</strong></p><ul><li>[ ] <strong>Quantify and Improve the Process:</strong></li><li>[ ] <strong>Measure Cycle Time / Throughput:</strong> Track the team&#39;s average delivery speed using Kanban metrics.</li><li>[ ] <strong>Measure Velocity:</strong> Track Scrum Velocity to improve forecasting accuracy.</li><li>[ ] <strong>Tune WIP Limits:</strong> Optimize WIP limits based on empirical data and team feedback.</li><li>[ ] <strong>Deepen XP Practices:</strong></li><li>[ ] <strong>Try Pair Programming:</strong> Use it for complex bug fixes or onboarding new team members.</li><li>[ ] <strong>Simple Design:</strong> Regularly review and discuss design complexity during retrospectives.</li><li>[ ] <strong>Embed the Culture:</strong></li><li>[ ] <strong>Remove Fear of Failure:</strong> Use TDD and retrospectives to foster a culture that treats mistakes as learning opportunities.</li><li>[ ] <strong>Encourage Team Self-Organization:</strong> Rather than issuing directives, the Scrum Master coaches the team to solve problems on their own.</li></ul><h4 id="_3-3-integrated-workflow-diagram-flow-of-a-single-sprint" tabindex="-1"><strong>3.3 Integrated Workflow Diagram: &quot;Flow of a Single Sprint&quot;</strong> <a class="header-anchor" href="#_3-3-integrated-workflow-diagram-flow-of-a-single-sprint" aria-label="Permalink to “3.3 Integrated Workflow Diagram: &quot;Flow of a Single Sprint&quot;”">​</a></h4>',39)),(t(),l(d,null,{default:a(()=>[c(o,{id:"mermaid-655",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%3Cb%3EProduct%20Backlog%3C%2Fb%3E%3Cbr%2F%3EPrioritized%20by%20PO%22%5D%20--%3E%20B%5BSprint%20Planning%20Meeting%5D%3B%0A%0A%20%20%20%20subgraph%20B%20%5B%22Scrum%20Event%3A%20Planning%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20B1%5B%22PO%3A%20What%3Cbr%2F%3EWhat%20to%20build%3F%22%5D%20--%3E%20B2%5B%22Dev%20Team%3A%20How%3Cbr%2F%3Eto%20build%20it%3F%3Cbr%2F%3EBreak%20down%20into%20Tasks%22%5D%3B%0A%20%20%20%20end%0A%0A%20%20%20%20B%20--%3E%20C%5B%22%3Cb%3ESprint%20Backlog%3C%2Fb%3E%3Cbr%2F%3ETask-level%20list%22%5D%3B%0A%20%20%20%20C%20--%3E%20D%5B%22Place%20Tasks%20on%20%3Cb%3EKanban%20Board%3C%2Fb%3E%22%5D%3B%0A%0A%20%20%20%20subgraph%20E%20%5B%22In-Sprint%20Task%20Execution%3Cbr%2F%3EXP%20%2B%20Kanban%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20F%5B%22To%20Do%3Cbr%2F%3EQueued%22%5D%20--%3E%20G%5B%22Development%3Cbr%2F%3EWIP%20Limit%3A%204%3Cbr%2F%3E**Apply%20XP%20Practices**%3Cbr%2F%3E-%20TDD%3Cbr%2F%3E-%20Pair%20Programming%3Cbr%2F%3E-%20CI%22%5D%3B%0A%20%20%20%20%20%20%20%20G%20--%3E%20H%5B%22Code%20Review%3Cbr%2F%3EWIP%20Limit%3A%202%22%5D%3B%0A%20%20%20%20%20%20%20%20H%20--%3E%20I%5BTesting%5D%3B%0A%20%20%20%20%20%20%20%20I%20--%3E%20J%5BDone%5D%3B%0A%20%20%20%20end%0A%0A%20%20%20%20D%20--%3E%20E%3B%0A%0A%20%20%20%20subgraph%20K%20%5B%22Scrum%20Event%3A%20Daily%22%5D%0A%20%20%20%20%20%20%20%20L%5B%22%3Cb%3EDaily%20Scrum%3C%2Fb%3E%3Cbr%2F%3EReview%20the%20board%20to%3Cbr%2F%3Eshare%20progress%20and%3Cbr%2F%3Eidentify%20blockers%22%5D%3B%0A%20%20%20%20end%0A%0A%20%20%20%20E%20--%3E%20L%3B%0A%20%20%20%20J%20--%3E%20M%5B%22%3Cb%3EIncrement%3C%2Fb%3E%3Cbr%2F%3EWorking%20Software%22%5D%3B%0A%0A%20%20%20%20subgraph%20N%20%5B%22Scrum%20Event%3A%20Inspect%20and%20Adapt%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20O%5B%22Sprint%20Review%3Cbr%2F%3EDemo%20Increment%20to%3Cbr%2F%3ECustomers%2FPO%20and%3Cbr%2F%3Eincorporate%20feedback%22%5D%3B%0A%20%20%20%20%20%20%20%20P%5B%22Sprint%20Retrospective%3Cbr%2F%3EIdentify%20process%20improvements%3Cbr%2F%3Ee.g.%20'Adjust%20WIP%20Limit'%3Cbr%2F%3E'Expand%20TDD%20coverage'%22%5D%3B%0A%20%20%20%20end%0A%0A%20%20%20%20M%20--%3E%20N%3B%0A%20%20%20%20O%20--%3E%20A%3B%0A%20%20%20%20P%20--%3E%20A%3B%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[g(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<hr><h3 id="conclusion-find-the-optimal-combination-for-your-context" tabindex="-1">Conclusion: Find the Optimal Combination for Your Context <a class="header-anchor" href="#conclusion-find-the-optimal-combination-for-your-context" aria-label="Permalink to “Conclusion: Find the Optimal Combination for Your Context”">​</a></h3><p>There is no &quot;silver bullet&quot; methodology. XP, Scrum, and Kanban are each tools with distinct strengths and areas of focus.</p><ul><li><strong>Teams building new products at high speed</strong> benefit greatly from an &quot;integrated approach&quot; that uses <strong>Scrum</strong> as the structural backbone, <strong>XP</strong> practices to guarantee quality, and a <strong>Kanban</strong> board to keep in-sprint workflow smooth.</li><li><strong>Teams focused primarily on maintenance</strong> can rely on <strong>Kanban</strong> as their primary system, hold regular <strong>Retrospectives (Scrum)</strong> to drive continuous improvement, and apply <strong>TDD (XP)</strong> to critical bug fixes.</li></ul><p>What matters most is that a team recognizes its own context and pain points, understands the principles and values behind these methodologies, and <strong>continuously experiments and improves</strong>. We hope this guide serves as a solid starting point for that journey.</p><hr><h2 id="software-engineering-velocity-and-the-limits-of-development-paradigms-after-ai-adoption" tabindex="-1">Software Engineering Velocity and the Limits of Development Paradigms After AI Adoption <a class="header-anchor" href="#software-engineering-velocity-and-the-limits-of-development-paradigms-after-ai-adoption" aria-label="Permalink to “Software Engineering Velocity and the Limits of Development Paradigms After AI Adoption”">​</a></h2><ul><li>Source: <a href="https://news.hada.io/topic?id=23013" target="_blank" rel="noreferrer">Should We Revisit Extreme Programming (XP) in the Age of AI?</a></li></ul><ul><li>Although AI tools and platform innovations have dramatically accelerated code generation, project success rates remain low and failure rates remain high.</li><li>The bottleneck is not speed—it is the lack of verification and alignment, and XP uses deliberate constraints to drive learning, alignment, and quality improvement.</li></ul><hr><h2 id="the-role-of-xp-a-counterweight-to-speed" tabindex="-1">The Role of XP: A Counterweight to Speed <a class="header-anchor" href="#the-role-of-xp-a-counterweight-to-speed" aria-label="Permalink to “The Role of XP: A Counterweight to Speed”">​</a></h2><ul><li>Unconstrained acceleration creates problems by stripping away opportunities for learning, catching mistakes, and course-correcting.</li><li>XP is designed to introduce intentional friction and constraints so teams keep moving in the right direction.</li><li>Representative practice: Pair programming deliberately cuts individual raw output in half.</li><li>While pair programming may halve raw output volume, it doubles positive outcomes such as shared understanding, trust, quality, and team-wide capability growth.</li></ul><hr><h2 id="xp-s-core-concerns-deepen-in-the-age-of-ai" tabindex="-1">XP&#39;s Core Concerns Deepen in the Age of AI <a class="header-anchor" href="#xp-s-core-concerns-deepen-in-the-age-of-ai" aria-label="Permalink to “XP&#39;s Core Concerns Deepen in the Age of AI”">​</a></h2><ul><li>As AI makes code generation effortless, the risk of mass-producing poorly verified software increases.</li><li>Unconstrained automated systems layer unverified logic on top of itself, worsening complexity and fragility.</li><li>Recent research demonstrates that LLM accuracy degrades as context windows grow longer.</li><li>This results in brittle code with high maintenance costs—the very kind of disorderly entropy XP was created to prevent.</li></ul><hr><h2 id="software-remains-a-human-endeavor" tabindex="-1">Software Remains a Human Endeavor <a class="header-anchor" href="#software-remains-a-human-endeavor" aria-label="Permalink to “Software Remains a Human Endeavor”">​</a></h2><ul><li>No matter how much AI advances, software fundamentally remains something built by humans for humans, shaped by organizational communication and culture.</li><li>The primary obstacles to delivery are not levels of automation, but human-centered factors such as alignment, shared context, clear outcomes, and user validation.</li><li>Core values of XP: Simplicity, Communication, Feedback, Respect, and Courage.</li></ul><hr><h2 id="from-feature-factory-to-delivering-real-value" tabindex="-1">From Feature Factory to Delivering Real Value <a class="header-anchor" href="#from-feature-factory-to-delivering-real-value" aria-label="Permalink to “From Feature Factory to Delivering Real Value”">​</a></h2><ul><li>Successful teams prioritize flow and feedback over raw velocity itself.</li><li>XP practices—small batches, continuous integration, automated testing, and collective ownership—drive adaptability and user centricity.</li><li>As code production accelerates even further, these practices become indispensable for managing quality, risk, and intent.</li></ul><hr><h2 id="lessons-from-history" tabindex="-1">Lessons from History <a class="header-anchor" href="#lessons-from-history" aria-label="Permalink to “Lessons from History”">​</a></h2><ul><li><p>CHAOS Report statistics:</p><ul><li>1994: 16% of projects succeeded on time and within budget.</li><li>2012: Improved to 37%.</li><li>2020: Fell back to 31%.</li></ul></li><li><p>Even after more than 20 years of innovation and transformation (Agile, DevOps, cloud native, AI, etc.), overall reliability improved by only 14 percentage points.</p></li><li><p>Toolchains alone cannot solve the problem.</p></li><li><p>This reaffirms the importance of choosing and applying the right methodology.</p></li></ul><hr><h2 id="what-is-needed-going-forward" tabindex="-1">What Is Needed Going Forward <a class="header-anchor" href="#what-is-needed-going-forward" aria-label="Permalink to “What Is Needed Going Forward”">​</a></h2><ol><li>Output is no longer the constraint: Code generation capacity now outpaces verification and alignment speed.</li><li>Strengthen outcome-oriented capabilities: Feedback, clear product direction, strong collaboration, and sound design are essential.</li><li>More human-centric processes are needed: Even as AI advances, continuous delivery still depends on collaboration.</li></ol><ul><li>An effective Product Operating Model emerges from human-centered operations built around collaboration, clarity, and flow.</li><li>When team strategy, operating rhythm, and engineering practices are tightly aligned—rather than relying on technical innovation (platforms) alone—a sustainable software delivery environment for the AI era becomes possible.</li></ul><hr><h2 id="conclusion-is-xp-still-necessary-in-the-ai-era" tabindex="-1">Conclusion: Is XP Still Necessary in the AI Era? <a class="header-anchor" href="#conclusion-is-xp-still-necessary-in-the-ai-era" aria-label="Permalink to “Conclusion: Is XP Still Necessary in the AI Era?”">​</a></h2><ul><li>Yes.</li><li>Amid ever-more-powerful tools, teams need a framework that anchors human-centric practices.</li><li>XP simultaneously provides team focus, empathy, shared understanding, and clear alignment toward the right goals.</li><li>Rather than chasing raw output speed, it focuses on meaningful direction and alignment within the team.</li><li>In an era of AI acceleration and unconstrained production, XP is one of the rare methodologies that reminds us software is still human work.</li></ul>',31))])}const P=i(m,[["render",p]]);export{w as __pageData,P as default};
